1	//! `Vec<Item>` + `ModelRequest` → Anthropic Messages request body.
2	//!
3	//! Rules per the SMA-317 spec § "Wire translation". The translator
4	//! produces a `serde_json::Value` rather than typed structs to keep the
5	//! wire-snapshot tests readable.
6	
7	use paigasus_helikon_core::{ContentPart, Item};
8	use serde_json::{json, Value};
9	
10	/// Output of [`translate_messages`]: the top-level `system` field (string
11	/// or block-array form) and the `messages` array.
12	pub(crate) struct TranslatedMessages {
13	    pub(crate) system: Option<Value>,
14	    pub(crate) messages: Value,
15	}
16	
17	/// Translate the conversation into Anthropic's request shape.
18	///
19	/// `system` is `None` when no `Item::System` is present. `messages` is
20	/// always an array.
21	pub(crate) fn translate_messages(items: &[Item]) -> TranslatedMessages {
22	    let mut system_text = String::new();
23	    let mut messages: Vec<Value> = Vec::new();
24	    let mut pending_tool_use: Vec<Value> = Vec::new();
25	    let mut pending_tool_results: Vec<Value> = Vec::new();
26	
27	    fn flush_pending_assistant(messages: &mut Vec<Value>, pending: &mut Vec<Value>) {
28	        if !pending.is_empty() {
29	            messages.push(json!({
30	                "role": "assistant",
31	                "content": std::mem::take(pending),
32	            }));
33	        }
34	    }
35	
36	    fn flush_pending_user(messages: &mut Vec<Value>, pending: &mut Vec<Value>) {
37	        if !pending.is_empty() {
38	            messages.push(json!({
39	                "role": "user",
40	                "content": std::mem::take(pending),
41	            }));
42	        }
43	    }
44	
45	    for item in items {
46	        match item {
47	            Item::System { content } => {
48	                flush_pending_assistant(&mut messages, &mut pending_tool_use);
49	                flush_pending_user(&mut messages, &mut pending_tool_results);
50	                if !system_text.is_empty() {
51	                    system_text.push('\n');
52	                }
53	                system_text.push_str(&text_of(content));
54	            }
55	            Item::UserMessage { content } => {
56	                flush_pending_assistant(&mut messages, &mut pending_tool_use);
57	                // Pending tool_results go at the front of this user turn.
58	                let mut blocks: Vec<Value> = std::mem::take(&mut pending_tool_results);
59	                blocks.extend(user_blocks(content).as_array().unwrap().iter().cloned());
60	                messages.push(json!({"role": "user", "content": blocks}));
61	            }
62	            Item::AssistantMessage { content, agent: _ } => {
63	                flush_pending_user(&mut messages, &mut pending_tool_results);
64	                flush_pending_assistant(&mut messages, &mut pending_tool_use);
65	                messages.push(json!({
66	                    "role": "assistant",
67	                    "content": assistant_blocks(content),
68	                }));
69	            }
70	            Item::ToolCall {
71	                call_id,
72	                name,
73	                args,
74	            } => {
75	                let block = json!({
76	                    "type": "tool_use",
77	                    "id": call_id,
78	                    "name": name,
79	                    "input": args,
80	                });
81	                if let Some(last) = messages.last_mut().filter(|m| m["role"] == "assistant") {
82	                    last["content"].as_array_mut().unwrap().push(block);
83	                } else {
84	                    pending_tool_use.push(block);
85	                }
86	            }
87	            Item::ToolResult { call_id, content } => {
88	                pending_tool_results.push(json!({
89	                    "type": "tool_result",
90	                    "tool_use_id": call_id,
91	                    "content": text_of(content),
92	                }));
93	            }
94	            _ => {
95	                tracing::warn!(
96	                    target: "paigasus::anthropic::translate",
97	                    "unknown Item variant; skipping",
98	                );
99	            }
100	        }
101	    }
102	
103	    flush_pending_assistant(&mut messages, &mut pending_tool_use);
104	    flush_pending_user(&mut messages, &mut pending_tool_results);
105	
106	    let system = if system_text.is_empty() {
107	        None
108	    } else {
109	        Some(Value::String(system_text))
110	    };
111	    TranslatedMessages {
112	        system,
113	        messages: Value::Array(messages),
114	    }
115	}
116	
117	fn text_of(parts: &[ContentPart]) -> String {
118	    let mut s = String::new();
119	    for p in parts {
120	        if let ContentPart::Text { text } = p {
121	            if !s.is_empty() {
122	                s.push('\n');
123	            }
124	            s.push_str(text);
125	        }
126	    }
127	    s
128	}
129	
130	fn user_blocks(content: &[ContentPart]) -> Value {
131	    use paigasus_helikon_core::MediaSource;
132	    let blocks: Vec<Value> = content
133	        .iter()
134	        .filter_map(|p| match p {
135	            ContentPart::Text { text } => Some(json!({"type": "text", "text": text})),
136	            ContentPart::ToolResult { call_id, content } => Some(json!({
137	                "type": "tool_result",
138	                "tool_use_id": call_id,
139	                "content": text_of(content),
140	            })),
141	            ContentPart::Image { source } => match source {
142	                MediaSource::Url { url } => Some(json!({
143	                    "type": "image",
144	                    "source": {"type": "url", "url": url},
145	                })),
146	                MediaSource::Base64 { mime_type, data } => Some(json!({
147	                    "type": "image",
148	                    "source": {
149	                        "type": "base64",
150	                        "media_type": mime_type,
151	                        "data": data,
152	                    },
153	                })),
154	                _ => {
155	                    tracing::warn!(
156	                        target: "paigasus::anthropic::translate",
157	                        "unsupported MediaSource variant; skipping image",
158	                    );
159	                    None
160	                }
161	            },
162	            _ => None,
163	        })
164	        .collect();
165	    Value::Array(blocks)
166	}
167	
168	fn assistant_blocks(content: &[ContentPart]) -> Value {
169	    let blocks: Vec<Value> = content
170	        .iter()
171	        .filter_map(|p| match p {
172	            ContentPart::Text { text } => Some(json!({"type": "text", "text": text})),
173	            ContentPart::ToolUse { call_id, name, args } => Some(json!({
174	                "type": "tool_use",
175	                "id": call_id,
176	                "name": name,
177	                "input": args,
178	            })),
179	            ContentPart::Reasoning { .. } => {
180	                tracing::warn!(
181	                    target: "paigasus::anthropic::translate",
182	                    "dropping ContentPart::Reasoning on input — signature round-trip not yet supported",
183	                );
184	                None
185	            }
186	            _ => None,
187	        })
188	        .collect();
189	    Value::Array(blocks)
190	}
191	
192	#[cfg(test)]
193	mod tests {
194	    use super::*;
195	
196	    fn text(t: &str) -> ContentPart {
197	        ContentPart::Text { text: t.to_owned() }
198	    }
199	
200	    #[test]
201	    fn system_collapses_into_top_level_string() {
202	        let items = vec![Item::System {
203	            content: vec![text("be helpful")],
204	        }];
205	        let out = translate_messages(&items);
206	        assert_eq!(out.system, Some(Value::String("be helpful".to_owned())));
207	        assert_eq!(out.messages, json!([]));
208	    }
209	
210	    #[test]
211	    fn multiple_system_items_concatenate_in_order() {
212	        let items = vec![
213	            Item::System {
214	                content: vec![text("first")],
215	            },
216	            Item::UserMessage {
217	                content: vec![text("hi")],
218	            },
219	            Item::System {
220	                content: vec![text("second")],
221	            },
222	        ];
223	        let out = translate_messages(&items);
224	        assert_eq!(
225	            out.system,
226	            Some(Value::String("first\nsecond".to_owned())),
227	            "all system items collapse into one top-level slot (order-loss vs surrounding turns)",
228	        );
229	    }
