231	    #[test]
232	    fn user_text_emits_text_block() {
233	        let items = vec![Item::UserMessage {
234	            content: vec![text("hello")],
235	        }];
236	        let out = translate_messages(&items);
237	        assert_eq!(
238	            out.messages,
239	            json!([{"role": "user", "content": [{"type": "text", "text": "hello"}]}]),
240	        );
241	    }
242	
243	    #[test]
244	    fn assistant_text_emits_text_block() {
245	        let items = vec![Item::AssistantMessage {
246	            content: vec![text("done")],
247	            agent: Some("planner".to_owned()),
248	        }];
249	        let out = translate_messages(&items);
250	        assert_eq!(
251	            out.messages,
252	            json!([{"role": "assistant", "content": [{"type": "text", "text": "done"}]}]),
253	        );
254	        // `agent` attribution is dropped (no Anthropic slot).
255	    }
