257	    #[test]
258	    fn assistant_reasoning_is_always_dropped() {
259	        let items = vec![Item::AssistantMessage {
260	            content: vec![
261	                ContentPart::Reasoning {
262	                    text: "scratch".to_owned(),
263	                },
264	                text("answer"),
265	            ],
266	            agent: None,
267	        }];
268	        let out = translate_messages(&items);
269	        let content = &out.messages[0]["content"];
270	        assert_eq!(content.as_array().unwrap().len(), 1);
271	        assert_eq!(content[0]["type"], "text");
272	        assert_eq!(content[0]["text"], "answer");
273	    }
274	
275	    #[test]
276	    fn tool_call_folds_into_preceding_assistant() {
277	        let items = vec![
278	            Item::AssistantMessage {
279	                content: vec![text("calling")],
280	                agent: None,
281	            },
282	            Item::ToolCall {
283	                call_id: "tu_1".to_owned(),
284	                name: "ping".to_owned(),
285	                args: json!({"host": "ex.com"}),
286	            },
287	        ];
288	        let out = translate_messages(&items);
289	        let msg = &out.messages[0];
290	        assert_eq!(msg["role"], "assistant");
291	        let blocks = msg["content"].as_array().unwrap();
292	        assert_eq!(blocks.len(), 2);
293	        assert_eq!(blocks[0], json!({"type": "text", "text": "calling"}));
294	        assert_eq!(blocks[1]["type"], "tool_use");
295	        assert_eq!(blocks[1]["id"], "tu_1");
296	        assert_eq!(blocks[1]["name"], "ping");
297	        assert_eq!(blocks[1]["input"], json!({"host": "ex.com"}));
298	    }
299	
300	    #[test]
301	    fn standalone_tool_calls_synthesize_assistant_carrier() {
302	        let items = vec![
303	            Item::ToolCall {
304	                call_id: "tu_a".to_owned(),
305	                name: "a".to_owned(),
306	                args: json!({}),
307	            },
308	            Item::ToolCall {
309	                call_id: "tu_b".to_owned(),
310	                name: "b".to_owned(),
311	                args: json!({"x": 1}),
312	            },
313	        ];
314	        let out = translate_messages(&items);
315	        assert_eq!(out.messages.as_array().unwrap().len(), 1);
316	        let msg = &out.messages[0];
317	        assert_eq!(msg["role"], "assistant");
318	        let blocks = msg["content"].as_array().unwrap();
319	        assert_eq!(blocks.len(), 2);
320	        assert_eq!(blocks[0]["id"], "tu_a");
321	        assert_eq!(blocks[1]["id"], "tu_b");
322	    }
