338	        let blocks = out.messages[0]["content"].as_array().unwrap();
339	        assert_eq!(blocks.len(), 2);
340	        assert_eq!(blocks[0]["type"], "text");
341	        assert_eq!(blocks[1]["type"], "tool_use");
342	        assert_eq!(blocks[1]["id"], "tu_x");
