346	    #[test]
347	    fn tool_result_coalesces_into_following_user_message() {
348	        let items = vec![
349	            Item::AssistantMessage {
350	                content: vec![ContentPart::ToolUse {
351	                    call_id: "tu_1".to_owned(),
352	                    name: "ping".to_owned(),
353	                    args: json!({}),
354	                }],
355	                agent: None,
356	            },
357	            Item::ToolResult {
358	                call_id: "tu_1".to_owned(),
359	                content: vec![text("pong")],
360	            },
361	            Item::UserMessage {
362	                content: vec![text("now what?")],
363	            },
364	        ];
365	        let out = translate_messages(&items);
366	        let arr = out.messages.as_array().unwrap();
367	        assert_eq!(arr.len(), 2, "must not produce consecutive user turns");
368	        assert_eq!(arr[0]["role"], "assistant");
369	        assert_eq!(arr[1]["role"], "user");
370	        let blocks = arr[1]["content"].as_array().unwrap();
371	        assert_eq!(blocks.len(), 2);
372	        assert_eq!(
373	            blocks[0]["type"], "tool_result",
374	            "tool_result precedes text"
375	        );
376	        assert_eq!(blocks[0]["tool_use_id"], "tu_1");
377	        assert_eq!(blocks[1]["type"], "text");
378	        assert_eq!(blocks[1]["text"], "now what?");
379	    }
