1	//! Translation between Paigasus carrier types and Anthropic wire format.
2	
3	pub(crate) mod cache;
4	pub(crate) mod request;
5	pub(crate) mod response_format;
6	pub(crate) mod tools;
7	
8	use paigasus_helikon_core::{ModelError, ModelRequest, ToolChoice};
9	use serde_json::{json, Value};
10	
11	use crate::builder::Config;
12	use crate::settings::ExtendedThinking;
13	use response_format::{
14	    synthesize_for_response_format, validate_conflict, validate_tool_names, Synthesized,
15	};
16	
17	/// Built request body + whether the stream translator should be in synthesis mode.
18	#[derive(Debug)]
19	pub(crate) struct PreparedRequest {
20	    pub(crate) body: Value,
21	    pub(crate) synthesizing_output: bool,
22	}
23	
24	/// Build the JSON request body from the caller's `ModelRequest` plus the
25	/// builder-baked `Config`. Runs all synchronous validation guards.
26	pub(crate) fn build_body(cfg: &Config, req: &ModelRequest) -> Result<PreparedRequest, ModelError> {
27	    validate_tool_names(&req.tools).map_err(|m| ModelError::Other(anyhow::anyhow!(m)))?;
28	    validate_conflict(
29	        req.model_settings.response_format.as_ref(),
30	        req.model_settings.tool_choice.as_ref(),
31	    )
32	    .map_err(|m| ModelError::Other(anyhow::anyhow!(m)))?;
33	
34	    let translated = request::translate_messages(&req.messages);
35	
36	    let mut tools_array = tools::translate_tools(&req.tools);
37	
38	    let Synthesized {
39	        tool,
40	        tool_choice,
41	        synthesizing,
42	    } = synthesize_for_response_format(req.model_settings.response_format.as_ref());
43	    if let Some(extra) = tool {
44	        if let Some(arr) = tools_array.as_array_mut() {
45	            arr.push(extra);
46	        }
47	    }
48	
49	    let mut messages = translated.messages;
50	    let system = cache::apply_cache_strategy(
51	        cfg.cache_strategy,
52	        translated.system,
53	        &mut tools_array,
54	        &mut messages,
55	    );
56	
57	    let mut body = serde_json::Map::new();
58	    body.insert("model".into(), Value::String(cfg.model_id.clone()));
59	    body.insert("stream".into(), Value::Bool(true));
60	    body.insert("messages".into(), messages);
61	    body.insert(
62	        "max_tokens".into(),
63	        Value::Number(
64	            req.model_settings
65	                .max_output_tokens
66	                .map(|m| m.into())
67	                .unwrap_or_else(|| cfg.max_output_default.into()),
68	        ),
69	    );
70	    if let Some(s) = system {
71	        body.insert("system".into(), s);
72	    }
73	    if tools_array
74	        .as_array()
75	        .map(|a| !a.is_empty())
76	        .unwrap_or(false)
77	    {
78	        body.insert("tools".into(), tools_array);
79	    }
80	
81	    // tool_choice: synthesis overrides caller; otherwise translate caller's preference.
82	    let tc_value = match tool_choice {
83	        Some(v) => Some(v),
84	        None => req
85	            .model_settings
86	            .tool_choice
87	            .as_ref()
88	            .map(translate_tool_choice),
89	    };
90	    if let Some(v) = tc_value {
91	        body.insert("tool_choice".into(), v);
92	    }
93	
94	    if let Some(t) = req.model_settings.temperature {
95	        body.insert("temperature".into(), json!(t));
96	    }
97	    if let Some(p) = req.model_settings.top_p {
98	        body.insert("top_p".into(), json!(p));
99	    }
100	    if let Some(k) = cfg.top_k {
101	        body.insert("top_k".into(), json!(k));
102	    }
103	    match cfg.extended_thinking {
104	        ExtendedThinking::Disabled => {}
105	        ExtendedThinking::Enabled { budget_tokens } => {
106	            body.insert(
107	                "thinking".into(),
108	                json!({"type": "enabled", "budget_tokens": budget_tokens}),
109	            );
110	        }
111	        ExtendedThinking::Adaptive => {
112	            body.insert("thinking".into(), json!({"type": "adaptive"}));
113	        }
114	    }
115	
116	    if req.model_settings.previous_response_id.is_some() {
117	        tracing::debug!(
118	            target: "paigasus::anthropic::translate",
119	            "previous_response_id is Anthropic-irrelevant; ignoring",
120	        );
121	    }
122	
123	    Ok(PreparedRequest {
124	        body: Value::Object(body),
125	        synthesizing_output: synthesizing,
126	    })
127	}
128	
129	fn translate_tool_choice(tc: &ToolChoice) -> Value {
130	    match tc {
131	        ToolChoice::Auto => json!({"type": "auto"}),
132	        ToolChoice::Required => json!({"type": "any"}),
133	        ToolChoice::None => json!({"type": "none"}),
134	        ToolChoice::Tool { name } => json!({"type": "tool", "name": name}),
135	        _ => json!({"type": "auto"}),
136	    }
137	}
138	
139	#[cfg(test)]
140	mod tests {
141	    use super::*;
142	    use crate::builder::AnthropicModelBuilder;
143	    use paigasus_helikon_core::{ContentPart, Item, ModelRequest, ResponseFormat, ToolDef};
144	
145	    fn cfg() -> Config {
146	        AnthropicModelBuilder::new("claude-sonnet-4-6")
147	            .api_key("sk-test")
148	            .build_config()
149	            .unwrap()
150	    }
151	
152	    fn user_text(s: &str) -> Item {
153	        Item::UserMessage {
154	            content: vec![ContentPart::Text { text: s.to_owned() }],
155	        }
156	    }
157	
158	    #[test]
159	    fn basic_request_has_model_messages_max_tokens_stream() {
160	        let mut req = ModelRequest::new();
161	        req.messages = vec![user_text("hi")];
162	        let p = build_body(&cfg(), &req).unwrap();
163	        assert_eq!(p.body["model"], "claude-sonnet-4-6");
164	        assert_eq!(p.body["stream"], true);
165	        assert!(p.body["messages"].is_array());
166	        assert_eq!(p.body["max_tokens"], 32_768);
167	        assert!(!p.synthesizing_output);
168	    }
169	
170	    #[test]
171	    fn caller_max_tokens_overrides_model_default() {
172	        let mut req = ModelRequest::new();
173	        req.messages = vec![user_text("hi")];
174	        req.model_settings.max_output_tokens = Some(1024);
175	        let p = build_body(&cfg(), &req).unwrap();
176	        assert_eq!(p.body["max_tokens"], 1024);
177	    }
178	
179	    #[test]
180	    fn tool_choice_none_emits_native_none() {
181	        let mut req = ModelRequest::new();
182	        req.messages = vec![user_text("hi")];
183	        req.tools = vec![ToolDef {
184	            name: "search".to_owned(),
185	            description: "".to_owned(),
186	            schema: serde_json::json!({}),
187	        }];
188	        req.model_settings.tool_choice = Some(ToolChoice::None);
189	        let p = build_body(&cfg(), &req).unwrap();
190	        assert_eq!(p.body["tool_choice"], serde_json::json!({"type": "none"}));
191	        assert!(
192	            p.body["tools"].is_array(),
193	            "tools stay in body so prefix matches cached turns"
194	        );
195	    }
196	
197	    #[test]
198	    fn json_schema_synthesizes_forced_tool() {
199	        let mut req = ModelRequest::new();
200	        req.messages = vec![user_text("Build a person.")];
201	        req.model_settings.response_format = Some(ResponseFormat::JsonSchema {
202	            name: "Person".to_owned(),
203	            schema: serde_json::json!({"type": "object"}),
204	            strict: false,
205	        });
206	        let p = build_body(&cfg(), &req).unwrap();
207	        assert!(p.synthesizing_output);
208	        assert_eq!(
209	            p.body["tool_choice"],
210	            serde_json::json!({"type": "tool", "name": "__paigasus_structured_output__"}),
211	        );
212	        let tools = p.body["tools"].as_array().unwrap();
213	        assert_eq!(tools.len(), 1);
214	        assert_eq!(tools[0]["name"], "__paigasus_structured_output__");
215	    }
216	
217	    #[test]
218	    fn reserved_tool_name_rejected_synchronously() {
219	        let mut req = ModelRequest::new();
220	        req.messages = vec![user_text("hi")];
221	        req.tools = vec![ToolDef {
222	            name: "__paigasus_structured_output__".to_owned(),
223	            description: "".to_owned(),
224	            schema: serde_json::json!({}),
225	        }];
226	        let err = build_body(&cfg(), &req).unwrap_err();
227	        assert!(matches!(err, ModelError::Other(_)));
228	    }
229	
230	    #[test]
231	    fn extended_thinking_adaptive_emits_adaptive_payload() {
232	        let mut cfg = cfg();
233	        cfg.extended_thinking = ExtendedThinking::Adaptive;
234	        let mut req = ModelRequest::new();
235	        req.messages = vec![user_text("hi")];
236	        let p = build_body(&cfg, &req).unwrap();
237	        assert_eq!(p.body["thinking"], serde_json::json!({"type": "adaptive"}));
238	    }
239	}
