        .invoke(req_with(vec![user("hi")]), CancellationToken::new())
        .await
        .unwrap();
    let first = s.next().await.expect("stream not empty");
    match first {
        Err(ModelError::RateLimited { retry_after_ms }) => {
            assert_eq!(retry_after_ms, Some(7_000));
