454	// ── Model-turn accumulation ─────────────────────────────────────────────────
455	
456	/// One fully-aggregated model turn.
457	///
458	/// Reassembled from a [`ModelEvent`] stream by [`ModelTurnAccumulator`]: the
459	/// concatenated text/reasoning deltas become at most one
460	/// [`crate::Item::AssistantMessage`], each distinct `ToolCallDelta` `call_id`
461	/// becomes one [`crate::Item::ToolCall`], `usage` is the last `Usage`
462	/// snapshot observed, and `finish_reason` is the terminal `Finish` reason.
463	#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
464	#[non_exhaustive]
465	pub struct ModelTurn {
466	    /// Reconstructed items: an optional leading `AssistantMessage` (text
467	    /// and/or reasoning content) followed by zero or more `ToolCall`s, in
468	    /// deterministic `call_id`-sorted order.
469	    pub items: Vec<crate::Item>,
470	    /// The last [`ModelEvent::Usage`] snapshot observed (last-wins; usage
471	    /// snapshots are never summed within a turn), or the zero default if
472	    /// the stream never emitted one.
473	    pub usage: crate::TokenUsage,
474	    /// Why the response ended.
475	    pub finish_reason: FinishReason,
476	}
477	
478	impl ModelTurn {
479	    /// Construct a `ModelTurn` directly from its parts.
480	    ///
481	    /// The normal path is [`ModelTurnAccumulator::finish`], which reassembles
